```typescript
/**
 * Orchestrator Entry Point
 *
 * Runs the orchestrator as an interactive agent session in a tmux pane.
 * Uses the SDK's createAgentSession + InteractiveMode for the TUI.
 *
 * Boot optimization: the orchestrator now absorbs work previously done in the CLI
 * (ensureGlobalRuntime, runMigrations, installThemes) so the CLI can spawn tmux
 * instantly. Stage 1 initialization is parallelized where possible.
 *
 * Profile-aware tool selection:
 *   - Solo profile (hybrid): full coding tools + dispatch_agent
 *   - Pair/multi profile (dispatch-only): read-only tools + dispatch_agent
 *
 * Extensions are loaded from config (.awoc/config.yaml) via EXTENSION_MAP.
 *
 * Environment variables:
 *   AWOC_PROJECT  — project working directory (default: cwd)
 *   AWOC_PROFILE  — workspace profile name (only set when user passes --profile)
 *   AWOC_MODEL    — optional model override (e.g., "anthropic/claude-opus-4-5")
 */

import { join } from "node:path";
import {
  DefaultResourceLoader,
  InteractiveMode,
  SessionManager,
  SettingsManager,
  codingTools,
  createAgentSession,
  createEventBus,
  readOnlyTools,
} from "@mariozechner/pi-coding-agent";
import type { ExtensionFactory } from "@mariozechner/pi-coding-agent";
import { exitCli } from "./cli/shared";
import {
  loadConfig,
  loadProfileByName,
  resolveOrchestratorModel,
  resolveOrchestratorThinking,
  resolveToolMode,
} from "./core/config";
import { DEFAULT_CONFIG, DEFAULT_PROFILES } from "./core/defaults";
import { ensureGlobalRuntime } from "./core/init";
import { resolvePackageRoot } from "./core/package-root";
import { registerApiProvidersOnRegistry } from "./core/providers/api-providers";
import { AWOC_AGENT_DIR, KNOWN_EXTENSIONS, createSharedAuth, resolveModel } from "./core/providers/shared";
import { installThemes } from "./cli/shared";
import { runMigrations } from "./migrations/runner";
import { awocCore } from "./extensions/awoc-core";
import { interop } from "./extensions/interop";
import { safety } from "./extensions/safety";
import { tasks } from "./extensions/tasks";
import { telemetry } from "./extensions/telemetry";
import { toolCounter } from "./extensions/tool-counter";

// Map config extension names to factory functions
const EXTENSION_MAP: Record<string, ExtensionFactory> = {
  "awoc-core.ts": awocCore,
  "safety.ts": safety,
  "tasks.ts": tasks,
  "tool-counter.ts": toolCounter,
  "interop.ts": interop,
  "telemetry.ts": telemetry,
};

export async function runOrchestratorEntry(): Promise<void> {
  // Suppress engine's built-in version check — AWOC manages its own update flow
  Bun.env.PI_SKIP_VERSION_CHECK = "1";

  const cwd = Bun.env.AWOC_PROJECT || process.cwd();
  const profileOverride = Bun.env.AWOC_PROFILE; // only set when user passes --profile
  const modelOverride = Bun.env.AWOC_MODEL;

  // --- Pre-config: idempotent setup previously done in CLI ---
  // These run before config load to ensure global dirs and migrations are current.
  await ensureGlobalRuntime();

  const migrationCtx = { projectRoot: cwd, userStateDir: AWOC_AGENT_DIR };
  const { failed } = await runMigrations(migrationCtx);
  if (failed.length > 0) {
    console.error("[awoc:orchestrator] Migration failed. Run 'awoc doctor' for details.");
    // Non-fatal: continue with defaults. Orchestrator should still boot.
  }

  const packageRoot = resolvePackageRoot(import.meta.dir);
  try {
    await installThemes(packageRoot);
  } catch {
    // Non-fatal: themes are cosmetic, continue boot.
  }

  // --- Stage 1: Parallel initialization (config, profile, auth have zero data deps) ---
  const [configResult, authResult] = await Promise.allSettled([
    loadConfig(undefined, cwd),
    createSharedAuth(),
  ]);

  let config: Awaited<ReturnType<typeof loadConfig>>;
  let configFallback: string | undefined;
  if (configResult.status === "fulfilled") {
    config = configResult.value;
  } else {
    const reason = configResult.reason instanceof Error ? configResult.reason.message : String(configResult.reason);
    console.warn(`[awoc:orchestrator] WARNING: Failed to load config: ${reason}. Using built-in defaults.`);
    config = { ...DEFAULT_CONFIG };
    configFallback = reason;
  }

  // Resolve profile name: env var (explicit --profile) → config.profile → "focus"
  const profileName = profileOverride ?? config.profile ?? "focus";

  // Load profile (depends on profileName from config)
  let profile: import("./core/config").ProfileConfig | null;
  let profileFallback: string | undefined;
  try {
    profile = await loadProfileByName(profileName);
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err);
    console.warn(
      `[awoc:orchestrator] WARNING: Failed to load profile '${profileName}': ${reason}. Using built-in 'solo' profile.`,
    );
    profile = DEFAULT_PROFILES.solo;
    profileFallback = reason;
  }

  // Resolve extension factories from config, warn on unknowns
  const extensionFactories: ExtensionFactory[] = [];
  for (const name of config.extensions) {
    const factory = EXTENSION_MAP[name];
    if (factory) {
      extensionFactories.push(factory);
    } else {
      console.warn(`[awoc] Unknown extension '${name}', skipping. Known: ${KNOWN_EXTENSIONS.join(", ")}`);
    }
  }

  // Determine tool mode from profile
  const toolMode = profile ? resolveToolMode(profile) : "hybrid";
  const tools = toolMode === "hybrid" ? codingTools : readOnlyTools;

  // Auth resolution
  let authStorage: Awaited<ReturnType<typeof createSharedAuth>>["authStorage"];
  let modelRegistry: Awaited<ReturnType<typeof createSharedAuth>>["modelRegistry"];
  if (authResult.status === "fulfilled") {
    ({ authStorage, modelRegistry } = authResult.value);
  } else {
    // Auth failed in parallel — retry synchronously as it's critical
    const auth = await createSharedAuth();
    authStorage = auth.authStorage;
    modelRegistry = auth.modelRegistry;
  }

  // Register API providers (e.g., Inception) on the model registry before resolution
  registerApiProvidersOnRegistry(modelRegistry, cwd);

  // Model priority: env var > profile.orchestrator.model > profile.models.orchestrator > auto-detect
  const effectiveModelString = resolveOrchestratorModel(profile, modelOverride);

  let model: import("@mariozechner/pi-ai").Model<import("@mariozechner/pi-ai").Api>;
  try {
    model = resolveModel(modelRegistry, effectiveModelString);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    const canFallbackToAuto =
      !!effectiveModelString && (msg.includes("has no authentication") || msg.includes("is not available"));

    if (canFallbackToAuto) {
      try {
        model = resolveModel(modelRegistry);
        console.warn(`[awoc:orchestrator] '${effectiveModelString}' unavailable; falling back to auto-selected model.`);
      } catch {
        console.error(`[awoc:orchestrator] ${msg}`);
        console.error("Hint: Run 'awoc login' to authenticate with a model provider.");
        exitCli(1);
      }
    } else {
      console.error(`[awoc:orchestrator] ${msg}`);
      if (msg.includes("No authenticated models")) {
        console.error("Hint: Run 'awoc login' to authenticate with a model provider.");
      }
      exitCli(1);
    }
  }

  // Event bus for extension communication
  const eventBus = createEventBus();

  // Resource loader — extension factories from config, no file-based discovery
  // Themes are loaded from agentDir/themes/ (installed by installThemes above)
  const resourceLoader = new DefaultResourceLoader({
    cwd,
    agentDir: AWOC_AGENT_DIR,
    eventBus,
    extensionFactories,
    noExtensions: true,
    noSkills: true,
  });
  await resourceLoader.reload();

  // Session manager — persistent sessions under ~/.awoc/agent/sessions/
  const sessionManager = SessionManager.create(cwd, join(AWOC_AGENT_DIR, "sessions"));

  // Settings — in-memory, suppress engine's startup listing
  const settingsManager = SettingsManager.inMemory({
    quietStartup: true,
  });

  // Resolve orchestrator thinking level from config cascade
  const orchestratorThinking = resolveOrchestratorThinking(profile, config);

  // Create the agent session with profile-determined tools
  let session: import("@mariozechner/pi-coding-agent").AgentSession;
  let modelFallbackMessage: string | undefined;
  try {
    const result = await createAgentSession({
      cwd,
      model,
      thinkingLevel: orchestratorThinking as "off" | "minimal" | "low" | "medium" | "high",
      tools,
      authStorage,
      modelRegistry,
      resourceLoader,
      sessionManager,
      settingsManager,
    });
    session = result.session;
    modelFallbackMessage = result.modelFallbackMessage;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[awoc:orchestrator] Failed to create agent session: ${msg}`);
    exitCli(1);
  }

  // Build recovery banner if any fallbacks were used
  let initialMessage: string | undefined;
  if (configFallback || profileFallback) {
    const lines: string[] = ["\u26a0 RECOVERY MODE: Config/profile loaded from defaults."];
    lines.push(`  Config:  ${configFallback ? `FALLBACK (${configFallback})` : "loaded"}`);
    lines.push(`  Profile: ${profileFallback ? `FALLBACK (${profileFallback})` : "loaded"}`);
    lines.push("  Fix the issues above and restart for full functionality.");
    initialMessage = lines.join("\n");
  }

  // Run interactive TUI
  const mode = new InteractiveMode(session, {
    initialMessage,
    modelFallbackMessage,
  });
  await mode.run();
}

if (import.meta.main) {
  runOrchestratorEntry().catch((err) => {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[awoc:orchestrator] Fatal: ${msg}`);
    if (Bun.env.AWOC_DEBUG) console.error(err);
    exitCli(1);
  });
}
```

