content.content:
  1→/**
  2→ * Orchestrator Entry Point
  3→ *
  4→ * Runs the orchestrator as an interactive agent session in a tmux pane.
  5→ * Uses the SDK's createAgentSession + InteractiveMode for the TUI.
  6→ *
  7→ * Boot optimization: the orchestrator now absorbs work previously done in the CLI
  8→ * (ensureGlobalRuntime, runMigrations, installThemes) so the CLI can spawn tmux
  9→ * instantly. Stage 1 initialization is parallelized where possible.
 10→ *
 11→ * Profile-aware tool selection:
 12→ *   - Solo profile (hybrid): full coding tools + dispatch_agent
 13→ *   - Pair/multi profile (dispatch-only): read-only tools + dispatch_agent
 14→ *
 15→ * Extensions are loaded from config (.awoc/config.yaml) via EXTENSION_MAP.
 16→ *
 17→ * Environment variables:
 18→ *   AWOC_PROJECT  — project working directory (default: cwd)
 19→ *   AWOC_PROFILE  — workspace profile name (only set when user passes --profile)
 20→ *   AWOC_MODEL    — optional model override (e.g., "anthropic/claude-opus-4-5")
 21→ */
 22→
 23→import { join } from "node:path";
 24→import {
 25→  DefaultResourceLoader,
 26→  InteractiveMode,
 27→  SessionManager,
 28→  SettingsManager,
 29→  codingTools,
 30→  createAgentSession,
 31→  createEventBus,
 32→  readOnlyTools,
 33→} from "@mariozechner/pi-coding-agent";
 34→import type { ExtensionFactory } from "@mariozechner/pi-coding-agent";
 35→import { exitCli } from "./cli/shared";
 36→import { installThemes } from "./cli/shared";
 37→import {
 38→  loadConfig,
 39→  loadProfileByName,
 40→  resolveOrchestratorModel,
 41→  resolveOrchestratorThinking,
 42→  resolveToolMode,
 43→} from "./core/config";
 44→import { DEFAULT_CONFIG, DEFAULT_PROFILES } from "./core/defaults";
 45→import { ensureGlobalRuntime } from "./core/init";
 46→import { resolvePackageRoot } from "./core/package-root";
 47→import { registerApiProvidersOnRegistry } from "./core/providers/api-providers";
 48→import { AWOC_AGENT_DIR, KNOWN_EXTENSIONS, createSharedAuth, resolveModel } from "./core/providers/shared";
 49→import { awocCore } from "./extensions/awoc-core";
 50→import { interop } from "./extensions/interop";
 51→import { safety } from "./extensions/safety";
 52→import { tasks } from "./extensions/tasks";
 53→import { telemetry } from "./extensions/telemetry";
 54→import { toolCounter } from "./extensions/tool-counter";
 55→import { runMigrations } from "./migrations/runner";
 56→
 57→// Map config extension names to factory functions
 58→const EXTENSION_MAP: Record<string, ExtensionFactory> = {
 59→  "awoc-core.ts": awocCore,
 60→  "safety.ts": safety,
 61→  "tasks.ts": tasks,
 62→  "tool-counter.ts": toolCounter,
 63→  "interop.ts": interop,
 64→  "telemetry.ts": telemetry,
 65→};
 66→
 67→export async function runOrchestratorEntry(): Promise<void> {
 68→  // Suppress engine's built-in version check — AWOC manages its own update flow
 69→  Bun.env.PI_SKIP_VERSION_CHECK = "1";
 70→
 71→  const cwd = Bun.env.AWOC_PROJECT || process.cwd();
 72→  const profileOverride = Bun.env.AWOC_PROFILE; // only set when user passes --profile
 73→  const modelOverride = Bun.env.AWOC_MODEL;
 74→
 75→  // --- Pre-config: idempotent setup previously done in CLI ---
 76→  // These run before config load to ensure global dirs and migrations are current.
 77→  await ensureGlobalRuntime();
 78→
 79→  const migrationCtx = { projectRoot: cwd, userStateDir: AWOC_AGENT_DIR };
 80→  const { failed } = await runMigrations(migrationCtx);
 81→  if (failed.length > 0) {
 82→    console.error("[awoc:orchestrator] Migration failed. Run 'awoc doctor' for details.");
 83→    // Non-fatal: continue with defaults. Orchestrator should still boot.
 84→  }
 85→
 86→  const packageRoot = resolvePackageRoot(import.meta.dir);
 87→  try {
 88→    await installThemes(packageRoot);
 89→  } catch {
 90→    // Non-fatal: themes are cosmetic, continue boot.
 91→  }
 92→
 93→  // --- Stage 1: Parallel initialization (config, profile, auth have zero data deps) ---
 94→  const [configResult, authResult] = await Promise.allSettled([loadConfig(undefined, cwd), createSharedAuth()]);
 95→
 96→  let config: Awaited<ReturnType<typeof loadConfig>>;
 97→  let configFallback: string | undefined;
 98→  if (configResult.status === "fulfilled") {
 99→    config = configResult.value;
100→  } else {
101→    const reason = configResult.reason instanceof Error ? configResult.reason.message : String(configResult.reason);
102→    console.warn(`[awoc:orchestrator] WARNING: Failed to load config: ${reason}. Using built-in defaults.`);
103→    config = { ...DEFAULT_CONFIG };
104→    configFallback = reason;
105→  }
106→
107→  // Resolve profile name: env var (explicit --profile) → config.profile → "focus"
108→  const profileName = profileOverride ?? config.profile ?? "focus";
109→
110→  // Load profile (depends on profileName from config)
111→  let profile: import("./core/config").ProfileConfig | null;
112→  let profileFallback: string | undefined;
113→  try {
114→    profile = await loadProfileByName(profileName);
115→  } catch (err) {
116→    const reason = err instanceof Error ? err.message : String(err);
117→    console.warn(
118→      `[awoc:orchestrator] WARNING: Failed to load profile '${profileName}': ${reason}. Using built-in 'solo' profile.`,
119→    );
120→    profile = DEFAULT_PROFILES.solo;
121→    profileFallback = reason;
122→  }
123→
124→  // Resolve extension factories from config, warn on unknowns
125→  const extensionFactories: ExtensionFactory[] = [];
126→  for (const name of config.extensions) {
127→    const factory = EXTENSION_MAP[name];
128→    if (factory) {
129→      extensionFactories.push(factory);
130→    } else {
131→      console.warn(`[awoc] Unknown extension '${name}', skipping. Known: ${KNOWN_EXTENSIONS.join(", ")}`);
132→    }
133→  }
134→
135→  // Determine tool mode from profile
136→  const toolMode = profile ? resolveToolMode(profile) : "hybrid";
137→  const tools = toolMode === "hybrid" ? codingTools : readOnlyTools;
138→
139→  // Auth resolution
140→  let authStorage: Awaited<ReturnType<typeof createSharedAuth>>["authStorage"];
141→  let modelRegistry: Awaited<ReturnType<typeof createSharedAuth>>["modelRegistry"];
142→  if (authResult.status === "fulfilled") {
143→    ({ authStorage, modelRegistry } = authResult.value);
144→  } else {
145→    // Auth failed in parallel — retry synchronously as it's critical
146→    const auth = await createSharedAuth();
147→    authStorage = auth.authStorage;
148→    modelRegistry = auth.modelRegistry;
149→  }
150→
151→  // Register API providers (e.g., Inception) on the model registry before resolution
152→  registerApiProvidersOnRegistry(modelRegistry, cwd);
153→
154→  // Model priority: env var > profile.orchestrator.model > profile.models.orchestrator > auto-detect
155→  const effectiveModelString = resolveOrchestratorModel(profile, modelOverride);
156→
157→  let model: import("@mariozechner/pi-ai").Model<import("@mariozechner/pi-ai").Api>;
158→  try {
159→    model = resolveModel(modelRegistry, effectiveModelString);
160→  } catch (err) {
161→    const msg = err instanceof Error ? err.message : String(err);
162→    const canFallbackToAuto =
163→      !!effectiveModelString && (msg.includes("has no authentication") || msg.includes("is not available"));
164→
165→    if (canFallbackToAuto) {
166→      try {
167→        model = resolveModel(modelRegistry);
168→        console.warn(`[awoc:orchestrator] '${effectiveModelString}' unavailable; falling back to auto-selected model.`);
169→      } catch {
170→        console.error(`[awoc:orchestrator] ${msg}`);
171→        console.error("Hint: Run 'awoc login' to authenticate with a model provider.");
172→        exitCli(1);
173→      }
174→    } else {
175→      console.error(`[awoc:orchestrator] ${msg}`);
176→      if (msg.includes("No authenticated models")) {
177→        console.error("Hint: Run 'awoc login' to authenticate with a model provider.");
178→      }
179→      exitCli(1);
180→    }
181→  }
182→
183→  // Event bus for extension communication
184→  const eventBus = createEventBus();
185→
186→  // Resource loader — extension factories from config, no file-based discovery
187→  // Themes are loaded from agentDir/themes/ (installed by installThemes above)
188→  const resourceLoader = new DefaultResourceLoader({
189→    cwd,
190→    agentDir: AWOC_AGENT_DIR,
191→    eventBus,
192→    extensionFactories,
193→    noExtensions: true,
194→    noSkills: true,
195→  });
196→  await resourceLoader.reload();
197→
198→  // Session manager — persistent sessions under ~/.awoc/agent/sessions/
199→  const sessionManager = SessionManager.create(cwd, join(AWOC_AGENT_DIR, "sessions"));
200→
201→  // Settings — in-memory, suppress engine's startup listing
202→  const settingsManager = SettingsManager.inMemory({
203→    quietStartup: true,
204→  });
205→
206→  // Resolve orchestrator thinking level from config cascade
207→  const orchestratorThinking = resolveOrchestratorThinking(profile, config);
208→
209→  // Create the agent session with profile-determined tools
210→  let session: import("@mariozechner/pi-coding-agent").AgentSession;
211→  let modelFallbackMessage: string | undefined;
212→  try {
213→    const result = await createAgentSession({
214→      cwd,
215→      model,
216→      thinkingLevel: orchestratorThinking as "off" | "minimal" | "low" | "medium" | "high",
217→      tools,
218→      authStorage,
219→      modelRegistry,
220→      resourceLoader,
221→      sessionManager,
222→      settingsManager,
223→    });
224→    session = result.session;
225→    modelFallbackMessage = result.modelFallbackMessage;
226→  } catch (err) {
227→    const msg = err instanceof Error ? err.message : String(err);
228→    console.error(`[awoc:orchestrator] Failed to create agent session: ${msg}`);
229→    exitCli(1);
230→  }
231→
232→  // Build recovery banner if any fallbacks were used
233→  let initialMessage: string | undefined;
234→  if (configFallback || profileFallback) {
235→    const lines: string[] = ["\u26a0 RECOVERY MODE: Config/profile loaded from defaults."];
236→    lines.push(`  Config:  ${configFallback ? `FALLBACK (${configFallback})` : "loaded"}`);
237→    lines.push(`  Profile: ${profileFallback ? `FALLBACK (${profileFallback})` : "loaded"}`);
238→    lines.push("  Fix the issues above and restart for full functionality.");
239→    initialMessage = lines.join("\n");
240→  }
241→
242→  // Run interactive TUI
243→  const mode = new InteractiveMode(session, {
244→    initialMessage,
245→    modelFallbackMessage,
246→  });
247→  await mode.run();
248→}
249→
250→if (import.meta.main) {
251→  runOrchestratorEntry().catch((err) => {
252→    const msg = err instanceof Error ? err.message : String(err);
253→    console.error(`[awoc:orchestrator] Fatal: ${msg}`);
254→    if (Bun.env.AWOC_DEBUG) console.error(err);
255→    exitCli(1);
256→  });
257→}
258→

